class Solution { int mask(string& word){int value=0;for(char ch:word)value|=1<<(ch-'a');return value;}public:int wordCount(vector<string>& startWords,vector<string>& targetWords){unordered_set<int> starts;for(string& word:startWords)starts.insert(mask(word));int answer=0;for(string& word:targetWords){int value=mask(word);for(int bits=value;bits;bits&=bits-1){int bit=bits&-bits;if(starts.count(value^bit)){++answer;break;}}}return answer;} };
